=== FILE: tb_crc8_block.v ===
`timescale 1ns / 1ps
// Self-checking constrained-random testbench for crc8_block.
// The reference model is written from interface_spec.md sections 2.1-2.3
// (start value 0xFF, polynomial 0x07, MSB first, no reflection, output
// inverted), not from the RTL. A table-driven second model cross-checks it.
// The stimulus uses an in-testbench xorshift32 generator, so a run with the
// same seed repeats on any simulator. Override the seed with +seed=<n>.
module tb_crc8_block;

    // ------------------------------------------------------------ DUT
    reg        clk;
    reg        rst_n;
    reg        init;
    reg        valid;
    reg  [7:0] data;
    wire [7:0] crc;

    crc8_block dut (
        .clk   (clk),
        .rst_n (rst_n),
        .init  (init),
        .valid (valid),
        .data  (data),
        .crc   (crc)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;

    // ------------------------------------------------------------ state
    integer passed;
    integer failed;
    integer mismatches;
    integer cycle_count;

    reg [7:0] model_state;
    reg       model_known;
    integer   frame_bytes;

    reg [7:0] crc_table [0:255];

    reg [31:0] rng;
    integer    seed_arg;

    reg [8*128-1:0] nonce;
    reg             have_nonce;
    reg [7:0]       ch;
    reg             started;
    integer         k;

    // corner counters
    integer n_bytes;
    integer n_byte00;
    integer n_byteFF;
    integer n_hold;
    integer n_hold_mid;
    integer n_rst_valid;
    integer n_rst_init;
    integer n_reset_mid;
    integer n_init_valid;
    integer n_init_mid;
    integer n_empty;
    integer n_long;

    // ------------------------------------------------------------ model
    // Spec 2.2, literally: for bit 7 down to 0, XOR the bit into the top bit
    // of the running value, shift left by one, and XOR 0x07 if the bit that
    // was shifted out was 1.
    function [7:0] spec_take_byte(input [7:0] s, input [7:0] d);
        integer b;
        reg [7:0] v;
        reg       out;
        begin
            v = s;
            for (b = 7; b >= 0; b = b - 1) begin
                v[7] = v[7] ^ d[b];
                out  = v[7];
                v    = v << 1;
                if (out)
                    v = v ^ 8'h07;
            end
            spec_take_byte = v;
        end
    endfunction

    task next_rand;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    task check_crc(input [7:0] expected, input [8*14-1:0] what);
        begin
            if (crc === expected) begin
                passed = passed + 1;
            end else begin
                failed     = failed + 1;
                mismatches = mismatches + 1;
                if (mismatches <= 10)
                    $display("TB MISMATCH %s cycle=%0d rst_n=%b init=%b valid=%b data=%h crc=%h expected=%h",
                             what, cycle_count, rst_n, init, valid, data, crc, expected);
            end
        end
    endtask

    // Hand-computed known answer: checks both the DUT and the model.
    task kat(input [7:0] expected, input [8*14-1:0] what);
        begin
            check_crc(expected, what);
            if ((model_state ^ 8'hFF) !== expected) begin
                failed = failed + 1;
                $display("TB MODEL ERROR %s: model gives %h, hand value %h",
                         what, model_state ^ 8'hFF, expected);
            end
        end
    endtask

    // One clock: drive away from the sampling edge, check between edges,
    // predict, then check after the edge.
    task cycle(input r, input i, input v, input [7:0] d);
        reg [7:0] exp_next;
        reg [7:0] tbl_next;
        reg       reload;
        begin
            @(negedge clk);
            rst_n = r;
            init  = i;
            valid = v;
            data  = d;
            #1;
            // CRC-FINAL: crc follows the running value only; new inputs do
            // not change it before an edge.
            if (model_known)
                check_crc(model_state ^ 8'hFF, "between-edges");

            reload = (!r) || i;
            if (!r)
                exp_next = 8'hFF;               // CRC-RESET
            else if (i)
                exp_next = 8'hFF;               // CRC-INIT: reload wins
            else if (v) begin
                exp_next = spec_take_byte(model_state, d);  // CRC-POLY/ORDER
                if (model_known) begin
                    tbl_next = crc_table[model_state ^ d];
                    if (tbl_next !== exp_next) begin
                        failed = failed + 1;
                        $display("TB MODEL ERROR: bitwise %h table %h (state %h data %h)",
                                 exp_next, tbl_next, model_state, d);
                    end
                end
            end else
                exp_next = model_state;         // CRC-HOLD

            // corner counting
            if (!r) begin
                if (v) n_rst_valid = n_rst_valid + 1;
                if (i) n_rst_init  = n_rst_init + 1;
                if (frame_bytes > 0) n_reset_mid = n_reset_mid + 1;
            end else if (i) begin
                if (v) n_init_valid = n_init_valid + 1;
                if (frame_bytes > 0) n_init_mid = n_init_mid + 1;
            end else if (v) begin
                if (model_known) begin
                    n_bytes = n_bytes + 1;
                    if (d == 8'h00) n_byte00 = n_byte00 + 1;
                    if (d == 8'hFF) n_byteFF = n_byteFF + 1;
                end
            end else if (model_known) begin
                n_hold = n_hold + 1;
                if (frame_bytes > 0) n_hold_mid = n_hold_mid + 1;
            end

            if (reload)
                frame_bytes = 0;
            else if (v && model_known) begin
                frame_bytes = frame_bytes + 1;
                if (frame_bytes == 16) n_long = n_long + 1;
            end

            @(posedge clk);
            #1;
            cycle_count = cycle_count + 1;
            if (reload || model_known) begin
                model_state = exp_next;
                model_known = 1'b1;
                check_crc(model_state ^ 8'hFF, "after-edge");
                if (reload) begin
                    check_crc(8'h00, "empty");    // CRC-EMPTY
                    n_empty = n_empty + 1;
                end
            end
        end
    endtask

    task run_phase(input integer n, input integer p_rst, input integer p_init, input integer p_valid);
        integer   c;
        reg       rr;
        reg       ri;
        reg       rv;
        reg [7:0] rd;
        reg [2:0] cls;
        begin
            $display("TB phase: %0d cycles, reset %0d/1000, init %0d/1000, valid %0d/1000",
                     n, p_rst, p_init, p_valid);
            for (c = 0; c < n; c = c + 1) begin
                next_rand; rr = ((rng % 1000) < p_rst);
                next_rand; ri = ((rng % 1000) < p_init);
                next_rand; rv = ((rng % 1000) < p_valid);
                next_rand; cls = rng[2:0];
                next_rand;
                case (cls)
                    3'd0:    rd = 8'h00;
                    3'd1:    rd = 8'hFF;
                    3'd2:    rd = 8'h01 << rng[2:0];
                    3'd3:    rd = ~(8'h01 << rng[2:0]);
                    default: rd = rng[15:8];
                endcase
                cycle(!rr, ri, rv, rd);
            end
        end
    endtask

    task require_min(input integer count, input integer minimum, input [8*24-1:0] name);
        begin
            if (count >= minimum)
                $display("TB coverage %s: %0d (min %0d) ok", name, count, minimum);
            else begin
                failed = failed + 1;
                $display("TB coverage %s: %0d below minimum %0d", name, count, minimum);
            end
        end
    endtask

    // ------------------------------------------------------------ main
    initial begin : main
        integer   i;
        integer   b2;
        reg [7:0] tv;

        rst_n = 1'b0;
        init  = 1'b0;
        valid = 1'b0;
        data  = 8'h00;

        passed = 0; failed = 0; mismatches = 0; cycle_count = 0;
        model_state = 8'h00; model_known = 1'b0; frame_bytes = 0;
        n_bytes = 0; n_byte00 = 0; n_byteFF = 0; n_hold = 0; n_hold_mid = 0;
        n_rst_valid = 0; n_rst_init = 0; n_reset_mid = 0; n_init_valid = 0;
        n_init_mid = 0; n_empty = 0; n_long = 0;

        // Table model: T[x] is x shifted eight times through polynomial 0x07.
        for (i = 0; i < 256; i = i + 1) begin
            tv = i[7:0];
            for (b2 = 0; b2 < 8; b2 = b2 + 1) begin
                if (tv[7]) tv = {tv[6:0], 1'b0} ^ 8'h07;
                else       tv = {tv[6:0], 1'b0};
            end
            crc_table[i] = tv;
        end

        nonce = 0;
        have_nonce = 1'b0;
        if ($value$plusargs("NIRMAAN_NONCE=%s", nonce))      have_nonce = 1'b1;
        else if ($value$plusargs("nirmaan_nonce=%s", nonce)) have_nonce = 1'b1;
        else if ($value$plusargs("nonce=%s", nonce))         have_nonce = 1'b1;
        else if ($value$plusargs("NONCE=%s", nonce))         have_nonce = 1'b1;

        rng = 32'h2C9E5A31;
        if ($value$plusargs("seed=%d", seed_arg))
            if (seed_arg != 0) rng = seed_arg;
        $display("TB crc8_block: seed=%0d (0x%08h)", rng, rng);

        // ---- directed prologue
        cycle(1'b0, 1'b0, 1'b0, 8'hA5);   // reset
        cycle(1'b0, 1'b0, 1'b1, 8'h3C);   // reset wins over a byte
        kat(8'h00, "kat-reset");
        cycle(1'b1, 1'b0, 1'b1, 8'h00);   kat(8'h0C, "kat-00");
        cycle(1'b1, 1'b1, 1'b0, 8'h00);   kat(8'h00, "kat-reload");
        cycle(1'b1, 1'b0, 1'b1, 8'hFF);   kat(8'hFF, "kat-FF");
        cycle(1'b1, 1'b0, 1'b1, 8'h00);   kat(8'hFF, "kat-FF-00");
        cycle(1'b1, 1'b1, 1'b1, 8'h5A);   kat(8'h00, "kat-init-wins");
        cycle(1'b1, 1'b0, 1'b1, 8'h01);   kat(8'h0B, "kat-01");
        cycle(1'b1, 1'b1, 1'b0, 8'h00);
        cycle(1'b1, 1'b0, 1'b1, 8'h80);   kat(8'h85, "kat-80");
        cycle(1'b1, 1'b0, 1'b0, 8'hC3);   kat(8'h85, "kat-hold1");
        cycle(1'b1, 1'b0, 1'b0, 8'h3C);   kat(8'h85, "kat-hold2");
        cycle(1'b0, 1'b1, 1'b1, 8'h77);   kat(8'h00, "kat-rst-init");

        // ---- constrained-random phases (knobs eased step by step)
        run_phase(300,  0,   50,  800);   // long frames, no reset
        run_phase(1500, 20,  80,  600);   // mixed traffic
        run_phase(500,  100, 250, 900);   // coincidence stress

        // ---- coverage of the corners the spec names
        require_min(n_bytes,      1000, "bytes taken");
        require_min(n_byte00,     20,   "byte 0x00 taken");
        require_min(n_byteFF,     20,   "byte 0xFF taken");
        require_min(n_hold_mid,   50,   "hold mid-frame");
        require_min(n_rst_valid,  10,   "reset with valid");
        require_min(n_rst_init,   5,    "reset with init");
        require_min(n_reset_mid,  5,    "reset mid-frame");
        require_min(n_init_valid, 20,   "init with valid");
        require_min(n_init_mid,   20,   "reload mid-frame");
        require_min(n_empty,      50,   "empty checks");
        require_min(n_long,       3,    "frames >= 16 bytes");

        $display("TB done: %0d cycles, %0d bytes, %0d holds, %0d mismatches",
                 cycle_count, n_bytes, n_hold, mismatches);

        if (!have_nonce) begin
            failed = failed + 1;
            $display("TB ERROR: no nonce plusarg found");
        end

        $write("NIRMAAN-SIM ");
        started = 1'b0;
        for (k = 127; k >= 0; k = k - 1) begin
            ch = nonce[k*8 +: 8];
            if (ch != 8'h00) started = 1'b1;
            if (started && ch != 8'h00) $write("%c", ch);
        end
        $display(" %0d passed, %0d failed", passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
